#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "config.h"
#include "dschat_build.h"   // generated by the Makefile from make variables

static void set(char *dst, size_t size, const char *src)
{
    snprintf(dst, size, "%s", src);
}

const char *config_voice_code(int lang)
{
    return lang == VOICE_IT ? "it" : "en";
}

void config_defaults(dschat_config *c)
{
    // Used when there is no settings file (or for keys it lacks). The SSID is
    // the only build-time value (DSCHAT, or melonAP for the melonDS ROM).
    memset(c, 0, sizeof(*c));
    set(c->ssid, sizeof(c->ssid), CFG_SSID);
    c->security = SEC_OPEN;
    c->dhcp = true;
    // starting values for "static" (the laptop AP's subnet, net/ap.conf)
    set(c->static_ip, sizeof(c->static_ip), "192.168.77.60");
    set(c->static_mask, sizeof(c->static_mask), "255.255.255.0");
    set(c->static_gw, sizeof(c->static_gw), "192.168.77.1");
    c->relay_host[0] = '\0';                // = the gateway
    c->relay_port = 4242;
    c->voice_lang = VOICE_EN;
    c->source = "built-in defaults";
}

// --------------------------------------------------------------------------
// Validators
// --------------------------------------------------------------------------

bool ipv4_parse(const char *s, uint8_t out[4])
{
    for (int part = 0; part < 4; part++)
    {
        if (*s < '0' || *s > '9')
            return false;
        if (*s == '0' && s[1] >= '0' && s[1] <= '9')
            return false;                       // no leading zeros (octal trap)
        unsigned v = 0;
        int digits = 0;
        while (*s >= '0' && *s <= '9')
        {
            v = v * 10 + (*s++ - '0');
            if (++digits > 3)
                return false;
        }
        if (v > 255)
            return false;
        out[part] = (uint8_t)v;
        if (part < 3)
        {
            if (*s != '.')
                return false;
            s++;
        }
    }
    return *s == '\0';
}

static uint32_t ip_u32(const uint8_t b[4])
{
    return ((uint32_t)b[0] << 24) | ((uint32_t)b[1] << 16) | ((uint32_t)b[2] << 8) | b[3];
}

bool netmask_valid(const char *s)
{
    uint8_t b[4];
    if (!ipv4_parse(s, b))
        return false;
    uint32_t m = ip_u32(b);
    if (m == 0)
        return false;
    uint32_t inv = ~m;
    return (inv & (inv + 1)) == 0;              // ones then zeros
}

static int hexval(char c)
{
    if (c >= '0' && c <= '9')
        return c - '0';
    if (c >= 'a' && c <= 'f')
        return c - 'a' + 10;
    if (c >= 'A' && c <= 'F')
        return c - 'A' + 10;
    return -1;
}

int wep_key_bytes(const char *key, uint8_t out[13])
{
    size_t n = strlen(key);
    for (size_t i = 0; i < n; i++)
    {
        if ((unsigned char)key[i] < 0x20 || (unsigned char)key[i] > 0x7E)
            return 0;
    }
    if (n == 5 || n == 13)
    {
        memcpy(out, key, n);
        return (int)n;
    }
    if (n == 10 || n == 26)
    {
        for (size_t i = 0; i < n; i += 2)
        {
            int hi = hexval(key[i]), lo = hexval(key[i + 1]);
            if (hi < 0 || lo < 0)
                return 0;
            out[i / 2] = (uint8_t)(hi << 4 | lo);
        }
        return (int)(n / 2);
    }
    return 0;
}

static bool printable(const char *s)
{
    for (; *s; s++)
    {
        if ((unsigned char)*s < 0x20 || (unsigned char)*s > 0x7E)
            return false;
    }
    return true;
}

bool config_validate(const dschat_config *c, char *why, size_t why_size)
{
    uint8_t ip[4], gw[4], mk[4], k[13];
    const char *problem = NULL;
    if (c->ssid[0] == '\0' || !printable(c->ssid))
        problem = "no network (SSID) chosen";
    else if (c->security == SEC_WEP && c->wep_key[0] == '\0')
        problem = "WEP key missing";
    else if (c->security == SEC_WEP && wep_key_bytes(c->wep_key, k) == 0)
        problem = "WEP key: 5/13 chars, 10/26 hex";
    else if (!c->dhcp && !ipv4_parse(c->static_ip, ip))
        problem = "static IP address is not valid";
    else if (!c->dhcp && !netmask_valid(c->static_mask))
        problem = "netmask is not valid";
    else if (!c->dhcp && !ipv4_parse(c->static_gw, gw))
        problem = "gateway is not valid";
    else if (!c->dhcp && (ipv4_parse(c->static_mask, mk), true)
             && (ip_u32(ip) & ip_u32(mk)) != (ip_u32(gw) & ip_u32(mk)))
        problem = "gateway not in the IP's subnet";
    else if (!c->dhcp && ip_u32(ip) == ip_u32(gw))
        problem = "IP and gateway are the same";
    else if (c->relay_host[0] && !ipv4_parse(c->relay_host, ip))
        problem = "relay address is not valid";
    else if (c->relay_port == 0)
        problem = "relay port must be 1-65535";
    if (why && why_size)
        snprintf(why, why_size, "%s", problem ? problem : "ok");
    return problem == NULL;
}

// --------------------------------------------------------------------------
// File format
// --------------------------------------------------------------------------

static char *trim(char *s)
{
    while (*s == ' ' || *s == '\t')
        s++;
    char *e = s + strlen(s);
    while (e > s && (e[-1] == ' ' || e[-1] == '\t' || e[-1] == '\r'))
        *--e = '\0';
    return s;
}

int config_parse(dschat_config *c, const char *text, char *err, size_t err_size)
{
    config_defaults(c);
    c->source = "settings file";
    int problems = 0;
    int lineno = 0;
    if (err && err_size)
        err[0] = '\0';

#define PROBLEM(...) do { \
        if (problems++ == 0 && err && err_size) { \
            int n_ = snprintf(err, err_size, "line %d: ", lineno); \
            if (n_ > 0 && (size_t)n_ < err_size) \
                snprintf(err + n_, err_size - n_, __VA_ARGS__); \
        } \
    } while (0)

    const char *p = text;
    while (*p)
    {
        char line[160];
        size_t n = strcspn(p, "\n");
        lineno++;
        bool too_long = n >= sizeof(line);
        size_t copy = too_long ? sizeof(line) - 1 : n;
        memcpy(line, p, copy);
        line[copy] = '\0';
        p += n;
        if (*p == '\n')
            p++;

        char *s = trim(line);
        if (*s == '\0' || *s == '#')
            continue;
        if (too_long)
        {
            PROBLEM("line too long");
            continue;
        }
        if (!printable(s))
        {
            PROBLEM("not plain text");
            continue;
        }
        char *eq = strchr(s, '=');
        if (eq == NULL)
        {
            PROBLEM("expected key = value");
            continue;
        }
        *eq = '\0';
        char *key = trim(s);
        char *val = trim(eq + 1);
        uint8_t b[13];

        if (strcmp(key, "version") == 0)
        {
            // informational; future formats may check it
        }
        else if (strcmp(key, "ssid") == 0)
        {
            if (val[0] == '\0' || strlen(val) > 32)
                PROBLEM("ssid must be 1-32 characters");
            else
                set(c->ssid, sizeof(c->ssid), val);
        }
        else if (strcmp(key, "security") == 0)
        {
            if (strcmp(val, "open") == 0)
                c->security = SEC_OPEN;
            else if (strcmp(val, "wep") == 0)
                c->security = SEC_WEP;
            else
                PROBLEM("security must be open or wep");
        }
        else if (strcmp(key, "wep_key") == 0)
        {
            if (val[0] != '\0' && wep_key_bytes(val, b) == 0)
                PROBLEM("wep_key: 5/13 chars or 10/26 hex digits");
            else
                set(c->wep_key, sizeof(c->wep_key), val);
        }
        else if (strcmp(key, "ip") == 0)
        {
            if (strcmp(val, "dhcp") == 0)
                c->dhcp = true;
            else if (strcmp(val, "static") == 0)
                c->dhcp = false;
            else
                PROBLEM("ip must be dhcp or static");
        }
        else if (strcmp(key, "static_ip") == 0 || strcmp(key, "static_gw") == 0)
        {
            char *dst = key[7] == 'i' ? c->static_ip : c->static_gw;
            if (!ipv4_parse(val, b))
                PROBLEM("bad IPv4 address for %s", key);
            else
                set(dst, 16, val);
        }
        else if (strcmp(key, "static_mask") == 0)
        {
            if (!netmask_valid(val))
                PROBLEM("bad netmask");
            else
                set(c->static_mask, sizeof(c->static_mask), val);
        }
        else if (strcmp(key, "relay_host") == 0)
        {
            if (strcmp(val, "auto") == 0 || val[0] == '\0')
                c->relay_host[0] = '\0';
            else if (!ipv4_parse(val, b))
                PROBLEM("relay_host must be auto or an IPv4 address");
            else
                set(c->relay_host, sizeof(c->relay_host), val);
        }
        else if (strcmp(key, "relay_port") == 0)
        {
            char *end;
            long v = strtol(val, &end, 10);
            if (val[0] == '\0' || *end != '\0' || v < 1 || v > 65535)
                PROBLEM("relay_port must be 1-65535");
            else
                c->relay_port = (uint16_t)v;
        }
        else if (strcmp(key, "voice_lang") == 0)
        {
            if (strcmp(val, "en") == 0)
                c->voice_lang = VOICE_EN;
            else if (strcmp(val, "it") == 0)
                c->voice_lang = VOICE_IT;
            else
                PROBLEM("voice_lang must be en or it");
        }
        else if (strcmp(key, "profile") == 0)
        {
            bool ok = strlen(val) <= 16;
            for (const char *q = val; ok && *q; q++)
                ok = (*q >= 'a' && *q <= 'z') || (*q >= '0' && *q <= '9') || *q == '_' || *q == '-';
            if (!ok)
                PROBLEM("profile: 1-16 of a-z 0-9 _ -");
            else
                set(c->profile, sizeof(c->profile), val);
        }
        else
        {
            PROBLEM("unknown key '%.20s'", key);
        }
    }
#undef PROBLEM
    return problems;
}

size_t config_serialise(const dschat_config *c, char *out, size_t cap)
{
    int n = snprintf(out, cap,
        "# DSChat settings - written by dschat.nds, safe to edit on a PC.\n"
        "# One \"key = value\" per line; lines starting with # are ignored.\n"
        "# Unknown or invalid lines are reported and replaced by defaults.\n"
        "version = 1\n"
        "\n"
        "# Wi-Fi network. The DS Lite can only join open or WEP networks.\n"
        "ssid = %s\n"
        "# open or wep\n"
        "security = %s\n"
        "# WEP key: 5 or 13 characters, or 10 or 26 hex digits (empty if open)\n"
        "wep_key = %s\n"
        "\n"
        "# dhcp or static; the static_* lines are used only with ip = static\n"
        "ip = %s\n"
        "static_ip = %s\n"
        "static_mask = %s\n"
        "static_gw = %s\n"
        "\n"
        "# Relay (the PC program): auto = the network's gateway, or an IPv4 address\n"
        "relay_host = %s\n"
        "relay_port = %u\n"
        "\n"
        "# Last used AI profile, chosen again on connect (empty = relay default)\n"
        "profile = %s\n"
        "\n"
        "# Voice input language (hold Y): en or it\n"
        "voice_lang = %s\n",
        c->ssid, c->security == SEC_WEP ? "wep" : "open", c->wep_key,
        c->dhcp ? "dhcp" : "static", c->static_ip, c->static_mask, c->static_gw,
        c->relay_host[0] ? c->relay_host : "auto", (unsigned)c->relay_port, c->profile,
        config_voice_code(c->voice_lang));
    if (n < 0 || (size_t)n >= cap)
        return 0;
    return (size_t)n;
}
